package countingsort;

public class CountingSort {

    private CountingSort() {}

    private static final class SortState {
        final int[] arr;
        final int min;
        final int[] counts;

        private SortState(int[] arr, int min, int[] counts) {
            this.arr = arr;
            this.min = min;
            this.counts = counts;
        }

        static SortState from(int[] arr) {
            int min = arr[0];
            int max = arr[0];
            for (int val : arr) {
                if (val < min) min = val;
                if (val > max) max = val;
            }
            long range = (long) max - min + 1;
            if (range > Integer.MAX_VALUE) {
                throw new IllegalArgumentException("Value range too large for counting sort: " + range);
            }
            int[] counts = new int[(int) range];
            for (int val : arr) {
                counts[val - min]++;
            }
            return new SortState(arr, min, counts);
        }

        void accumulateCounts() {
            for (int i = 1; i < counts.length; i++) {
                counts[i] += counts[i - 1];
            }
        }

        int[] buildSorted() {
            int[] sorted = new int[arr.length];
            for (int i = arr.length - 1; i >= 0; i--) {
                int idx = arr[i] - min;
                sorted[counts[idx] - 1] = arr[i];
                counts[idx]--;
            }
            return sorted;
        }
    }

    public static int[] sort(int[] arr) {
        if (arr == null) {
            throw new IllegalArgumentException("Input array cannot be null");
        }
        if (arr.length == 0) {
            return new int[0];
        }

        SortState state = SortState.from(arr);
        state.accumulateCounts();
        return state.buildSorted();
    }
}

